@@ -0,0 +1,31 @@
+// Sites: the kitchens Larder serves. Every location belongs to one site;
+// batches belong to the site of their location. Items, suppliers, recipes
+// and dishes are shared by all sites.
+import { AppError } from "../errors.js";
+
+/** The site used when a request names none. */
+export const DEFAULT_SITE = "main";
+
+/** Every site, in list order. */
+export function listSites(store) {
+  return [...(store.data.sites ?? [])];
+}
+
+/** One site, or AppError unknown_site. */
+export function getSite(store, id) {
+  const site = (store.data.sites ?? []).find((s) => s.id === id);
+  if (!site) throw new AppError("unknown_site", { id });
+  return site;
+}
+
+/** Ids of the locations in a site. */
+export function siteLocations(store, site) {
+  return store.data.locations.filter((l) => l.site === site).map((l) => l.id);
+}
+
+/** A batch filter for one site; `null` matches every site. */
+export function inSite(store, site) {
+  if (site === null) return () => true;
+  const ids = new Set(siteLocations(store, site));
+  return (b) => ids.has(b.location);
+}
