@@ -0,0 +1,76 @@
+import test from "node:test";
+import assert from "node:assert/strict";
+import { migrate } from "../src/db/migrations.js";
+import { app, seed } from "./helpers.js";
+
+const ANNEX = { "X-Larder-Site": "annex" };
+
+// A store with one annex batch of onion (item 1) in the annex fridge.
+async function withAnnexStock() {
+  const ctx = app();
+  const { store, handle } = ctx;
+  const order = (await handle({ method: "POST", path: "/orders", body: { supplierId: 1, lines: [{ itemId: 1, qty: 3 }] } })).body;
+  await handle({ method: "POST", path: `/orders/${order.id}/send` });
+  const res = await handle({ method: "POST", path: `/orders/${order.id}/receive`, body: { lots: [{ lot: "AX-1", expires: "2026-10-30", location: "annex-fridge" }] } });
+  assert.equal(res.status, 200);
+  return { ...ctx, batchId: res.body.batches[0].id, store };
+}
+
+test("schema 2 files open with every location in site main", () => {
+  const v2 = seed();
+  v2.schemaVersion = 2;
+  delete v2.sites;
+  v2.locations = v2.locations.filter((l) => l.site === "main").map(({ site, ...l }) => l);
+  const data = migrate(v2);
+  assert.equal(data.schemaVersion, 3);
+  assert.deepEqual(data.sites.map((s) => s.id), ["main"]);
+  assert.ok(data.locations.every((l) => l.site === "main"));
+  assert.equal(data.batches.length, v2.batches.length);
+});
+
+test("an unknown site is a 400 with its own code", async () => {
+  const { handle } = app();
+  const res = await handle({ path: "/items", headers: { "x-larder-site": "attic" } });
+  assert.equal(res.status, 400);
+  assert.equal(res.body.error.code, "unknown_site");
+  assert.match(res.body.error.message, /attic/);
+});
+
+test("stock, batches, alerts and value only see the request's site", async () => {
+  const { handle, batchId } = await withAnnexStock();
+  const mainItems = (await handle({ path: "/items" })).body;
+  const annexItems = (await handle({ path: "/items", headers: ANNEX })).body;
+  assert.equal(mainItems.find((i) => i.id === 1).onHand, 10);
+  assert.equal(annexItems.find((i) => i.id === 1).onHand, 3);
+  assert.equal(annexItems.find((i) => i.id === 4).onHand, 0);
+  assert.deepEqual((await handle({ path: "/batches", headers: ANNEX })).body.map((b) => b.id), [batchId]);
+  assert.ok(!(await handle({ path: "/batches" })).body.some((b) => b.id === batchId));
+  assert.equal((await handle({ path: `/batches/${batchId}` })).status, 404);
+  assert.equal((await handle({ path: `/batches/${batchId}`, headers: ANNEX })).status, 200);
+  assert.equal((await handle({ path: "/batches/6", headers: ANNEX })).status, 404);
+  const alerts = (await handle({ path: "/alerts", headers: ANNEX })).body;
+  assert.deepEqual(alerts.expiring.map((b) => b.lot), ["AX-1"]);
+  assert.ok(alerts.lowStock.some((i) => i.name === "flour"));
+  const value = (await handle({ path: "/reports/stock-value", headers: ANNEX })).body;
+  assert.equal(value.totalCents, 3 * 180);
+  // Shared data is the same for both sites.
+  assert.equal((await handle({ path: "/items", headers: ANNEX })).body.length, mainItems.length);
+});
+
+test("cooking uses only the request's site", async () => {
+  const { handle, store } = await withAnnexStock();
+  const before = JSON.stringify(store.data.batches);
+  const res = await handle({ method: "POST", path: "/recipes/1/cook", headers: ANNEX, body: { portions: 1 } });
+  assert.equal(res.status, 409);
+  assert.equal(JSON.stringify(store.data.batches), before);
+});
+
+test("stock-takes only see the request's site", async () => {
+  const { handle, batchId } = await withAnnexStock();
+  assert.equal((await handle({ method: "POST", path: "/stocktakes", headers: ANNEX, body: { location: "dry" } })).status, 400);
+  const take = (await handle({ method: "POST", path: "/stocktakes", headers: ANNEX, body: { location: "annex-fridge" } })).body;
+  assert.equal((await handle({ method: "POST", path: `/stocktakes/${take.id}/counts`, body: { batchId, counted: 2 } })).status, 404);
+  await handle({ method: "POST", path: `/stocktakes/${take.id}/counts`, headers: ANNEX, body: { batchId, counted: 2 } });
+  const res = await handle({ method: "POST", path: `/stocktakes/${take.id}/finish`, headers: ANNEX });
+  assert.deepEqual(res.body.lines, [{ batchId, expected: 3, counted: 2, diff: -1 }]);
+});
